// Links between sheet data and an (optional) compendium of notes, e.g. one generated by
// ttrpg-convert-cli. Pure: the list of notes is collected by the caller (Obsidian vault in the
// plugin, file system in Node scripts), so this works the same everywhere.
import { TOKEN } from "./build.ts";
import type { Compendium } from "../rules/engine.ts";

export interface NoteInfo {
  path: string;   // vault path without ".md", e.g. "Compendium/compendium/spells/fireball"
  alias: string;  // first alias / title, e.g. "Fireball"
  source: string; // source code from the ttrpg tag ".../compendium/src/5e/<source>", e.g. "phb"
}

const lc = (s: string | number | null | undefined) => String(s ?? "").toLowerCase();
/**
 * A 5etools source id as ttrpg-convert-cli writes it in its source tags: lowercased and otherwise
 * unchanged, so homebrew ids keep their other characters ("LLAR:E" -> "llar:e"). Used on both
 * sides, for the notes' tags and for the sheet data's sources.
 */
export const sourceTag = (source: string | null | undefined) => lc(source);
/** the source in a ttrpg-convert-cli source tag, ".../compendium/src/5e/<source>", up to the end of the tag */
const SOURCE_TAG = /compendium\/src\/5e\/([^\s/"',\]]+)/;
export const sourceOfTag = (tag: string): string | null => {
  const m = tag.match(SOURCE_TAG)?.[1];
  return m ? sourceTag(m) : null;
};

/**
 * Names a note stands for: its alias, and for a variant background also the 5etools name.
 * ttrpg-convert-cli titles "Variant Criminal (Spy)" as "Criminal (Spy) (Variant)".
 */
function namesOf(kind: string, alias: string): string[] {
  const variant = kind === "backgrounds" ? alias.match(/^(.+) \(Variant\)$/i)?.[1] : undefined;
  return variant ? [alias, `Variant ${variant}`] : [alias];
}

export class Linker {
  private exact = new Map<string, string>();
  private byName = new Map<string, string>();
  root: string | null;
  constructor(root: string | null, notes: NoteInfo[]) {
    this.root = root;
    for (const n of notes) {
      // kind = folder right under "<root>/compendium/", e.g. spells, races, classes
      const m = n.path.match(/\/compendium\/([^/]+)\//);
      if (!m) continue;
      for (const name of namesOf(m[1], n.alias)) {
        this.exact.set(`${m[1]}|${lc(name)}|${sourceTag(n.source)}`, n.path);
        if (!this.byName.has(`${m[1]}|${lc(name)}`)) this.byName.set(`${m[1]}|${lc(name)}`, n.path);
      }
    }
  }
  get enabled() { return !!this.root && this.exact.size > 0; }
  /** note for an entity of a kind (spells, races, classes, …), preferring the same source */
  note(kind: string, name: string, source?: string): string | null {
    return this.exact.get(`${kind}|${lc(name)}|${sourceTag(source)}`) ?? this.byName.get(`${kind}|${lc(name)}`) ?? null;
  }
  /** heading inside a rules note, e.g. rule("conditions", "Blinded") */
  rule(file: string, heading: string): string | null {
    return this.enabled ? `${this.root}/rules/${file}#${heading}` : null;
  }
  has(kind: string, name: string, source: string) { return this.exact.has(`${kind}|${lc(name)}|${sourceTag(source)}`); }

  /** replace ⟦kind|name|source|display⟧ tokens with wikilinks, or plain text when there is no note */
  text(s: string): string {
    return s.replace(TOKEN, (_m, kind: string, name: string, source: string, display: string) => {
      const target = kind.startsWith("rule:") ? (this.enabled ? this.rule(kind.slice(5), name) : null) : this.note(kind, name, source);
      return target ? `[[${target}|${display}]]` : display;
    });
  }

  /** fill in the `link` of every entity (and of class/subclass features) */
  attach(data: Compendium): Compendium {
    for (const r of data.races) {
      for (const s of r.subraces) s.link = this.note("races", `${r.name} (${s.name})`, s.source);
      r.link = this.note("races", r.name, r.source) ?? r.subraces.find((s) => s.link)?.link ?? null;
    }
    for (const c of data.classes) {
      c.link = this.note("classes", c.name, c.source);
      for (const f of c.features) f.link = c.link ? `${c.link}#${f.name} (Level ${f.level})` : null;
      for (const sc of c.subclasses) {
        sc.link = this.note("classes", sc.name, sc.source);
        for (const f of sc.features) f.link = sc.link ? `${sc.link}#${f.name} (Level ${f.level})` : null;
      }
    }
    for (const b of data.backgrounds) {
      b.link = this.note("backgrounds", b.name, b.source);
      if (b.feature) b.feature.link = b.link ? `${b.link}#${b.feature.heading || "Feature: " + b.feature.name}` : null;
    }
    for (const x of data.feats) x.link = this.note("feats", x.name, x.source);
    for (const x of data.spells) x.link = this.note("spells", x.name, x.source);
    for (const x of data.items) x.link = this.note("items", x.name, x.source);
    return data;
  }
}

/** Parse a compendium note's frontmatter text into NoteInfo (used by the Node scripts). */
export function noteInfoFromText(path: string, text: string): NoteInfo | null {
  const fm = text.replace(/\r\n/g, "\n").match(/^---\n([\s\S]*?)\n---/)?.[1] ?? "";
  const alias = fm.match(/aliases:\n- "?([^"\n]*)"?/)?.[1];
  const source = sourceOfTag(fm);
  return alias && source ? { path, alias, source } : null;
}
